insert into public.games (id, kind, type, category, title, noun, text, dict) values
  ('bible', 'curated', 'hidden-words', 'Bible', 'The classic', 'books of the Bible', 'There are books of the Bible in this paragraph. Can you find them? This is a most remarkable puzzle. It was found by a gentleman in an airplane seat pocket on a flight from Los Angeles to Honolulu. Keeping him occupied for hours. He enjoyed it so much he passed it on to some friends. One friend from Illinois worked on this while fishing from his john boat. Another friend studied it while playing his banjo. Elaine Taylor, a columnist friend was so intrigued by it she mentioned it in her weekly newspaper column. Another friend judges the job of solving this puzzle so involving, she brews a cup of tea to help her nerves. There will be some names that are really easy to spot. That''s a fact. Some people, however, will soon find themselves in a jam, especially since the book names are not necessarily capitalized. Truthfully, from answers we get, we are forced to admit it usually takes a minister or scholar to see some of them at the worst. Research has shown that something in our genes is responsible for the difficulty we have in seeing the book in this paragraph. During a recent fund raising event, which featured this puzzle, the Alpha Delta Phi lemonade booth set a new sales record. The local paper, The Chronicle, surveyed over 200 patrons who reported that this puzzle was one of the most difficult they had ever seen. As Daniel Humana humbly puts it, the books are all right there in plain view hidden from sight. Those able to find all of them will hear lamentations from those who have to be shown. One revelation that may help is that books like Timothy and Samuel may occur without their numbers. Also, keep in mind that punctuation and spacers in the middle are normal. A chipper attitude will help you compete really well against those who claim to know the answers. Remember there is no need for a mad exodus, there really are books of the Bible lurking somewhere in the paragraph waiting to be found.', '["Genesis","Exodus","Leviticus","Numbers","Deuteronomy","Joshua","Judges","Ruth","Samuel","Kings","Chronicles","Ezra","Nehemiah","Esther","Job","Psalms","Proverbs","Ecclesiastes","Isaiah","Jeremiah","Lamentations","Ezekiel","Daniel","Hosea","Joel","Amos","Obadiah","Jonah","Micah","Nahum","Habakkuk","Zephaniah","Haggai","Zechariah","Malachi","Matthew","Mark","Luke","John","Acts","Romans","Corinthians","Galatians","Ephesians","Philippians","Colossians","Thessalonians","Timothy","Titus","Philemon","Hebrews","James","Peter","Jude","Revelation"]'::jsonb),
  ('science', 'curated', 'hidden-words', 'Science', 'In the lab', 'science words', 'Pat omitted one detail at the lab. Carla serves tea in the attic while Tom asserted that a cider break would help. Hi, Ron, said Mac. Ellen saw a vessel drift past the window. The big energy of the team was all for bits of progress and one onion sandwich. Oh, my, Pat said, we shall ensure it works.', '["atom","heat","mass","acid","iron","cell","wave","gene","orbit","neon","ohm","lens","laser","ion","gas","volt","force"]'::jsonb),
  ('ai', 'curated', 'hidden-words', 'AI', 'A walk with Linda', 'AI words', 'Linda talked her friends into a long walk. Mo, deliver the dog to kennel first, she said, then follow a gentle path. Bob, I asked, is this the way? Each atlas we had was old. Lolo, open the gate. We passed street art, rain on the stones and a hollow log, icy from the night. Rob, otters live here, Lolo whispered.', '["data","model","token","agent","bias","chat","loop","train","logic","robot","code","graph","neural","prompt"]'::jsonb),
  ('history', 'curated', 'hidden-words', 'History', 'Lake weekend', 'history words', 'Pedro mentioned a trip at Roy''s party. It was part adventure, part rest. We slept in cabins by the lake. Ma, yawning, sent Stu, Dora and me for Ted''s boat. We shared her apples on the dock.', '["rome","troy","sparta","inca","maya","tudor","fort","era","king","war","age","empire"]'::jsonb),
  ('general', 'curated', 'hidden-words', 'General', 'Hidden colours', 'colours', 'I am Bert, said the man at the top lumber yard. Carl, I met Lucy, Anne and Raj, adept builders, there. We set a lamp on a big old table so live music could play while Ana, vying for attention, sang.', '["amber","plum","lime","cyan","jade","teal","gold","olive","navy","red","tan","ruby","rose","pink","blue","grey"]'::jsonb),
  ('nigeria', 'curated', 'hidden-words', 'Names', 'Nigerian names', 'Nigerian names', 'The theme Kara chose for the party was simple. Today, on the porch, we put under a jumbo lamp a pink emerald and a bowl of fruit. Lisa, nice as ever, made lemonade. Much energy filled the room when the drama, Kay said, began. Rob, is it true they emigrated from USA to Lagos? Take mine, Pa, David said. It was a life mission to bike home in the breeze. At the table: Litchi, Omar asked? No, kimchi, Buz ordered. Mochi, Mar? Okey dokey. Ok, unless it rains, we go to Lucy''s next. Another loaf, Ola? Bit much, she said.', '["Chioma","Chibuzor","Chimaroke","Chima","Fola","Kunle","Tolu","Afolabi","Emeka","Dayo","Tunde","Bola","Nkem","Sani","Dele","Uche","Amaka","Bisi","Yemi","Musa","Tola","Kemi","Ada","Femi","Tobi","Eze","Chidi","Ngozi","Segun","Kola","Wale","Bayo","Seun","Funmi","Chika","Nneka","Dapo","Tayo","Jide","Lanre","Sade","Toyin","Ebere","Osas","Efe"]'::jsonb),
  ('french', 'curated', 'hidden-words', 'Names', 'French names', 'French names', 'Omar, I eat here often, said a man only I knew. The spa ultimately closed, so we met at the café when Richard arrived. Lulu, cook something, he laughed. We can nearly see the mile marker from the table on the terrace. Lulu ordered tea and red plums. Where are my keys? No elevator here, Omar sighed. Your energy is great, she said, and gave a hug, Oscar included.', '["Marie","Manon","Paul","Henri","Luc","Anne","Emile","Leon","Andre","Remy","Noel","Rene","Hugo","Pierre","Jean","Louis","Claude","Yves","Jules","Odile","Sophie","Chloe","Camille","Julien","Zoe","Theo","Elise","Margot","Lucas","Adele","Aline","Colette","Denis","Fabien"]'::jsonb),
  ('football', 'curated', 'hidden-words', 'Football', 'Pitch side', 'football words and players', 'Sal, ahead of us, was the first to order. Lisa, Kate and Bob, Alex too, went for iced tea while Sara mostly watched the games since noon. Oscar drove, then Ryan took a nearly empty bus. It was a very long day. A top electrician fixed the lights, and we had one tea each. They go all the way up the hill, past a hippo statue, for the view.', '["Salah","Saka","Bale","Rice","Ramos","Messi","Henry","Kane","Pele","Goal","Post","Card","Save","Net","Ball","Pass","Kick","Foul","Penalty","Keeper","Offside","Pitch","Corner","Xavi","Kaka","Pogba","Drogba","Rooney","Mbappe","Zidane","Ronaldo","Modric","Foden","Pace","Header","Tackle","Striker","Winger","Coach","Referee"]'::jsonb),
  ('health', 'curated', 'hidden-words', 'Health', 'Medicine and nursing', 'health and nursing words', 'The doc asked a chef to secure a table after lunch. The art on his wall came from a war documentary set. Clara shopped for red ripe tomatoes, if everyone agreed. Georg, answering the alarm, ran to stop illegal parking outside. They do sell music as the day ends. Paul, certain of the time, said the bus can only take twelve. Oscar, eat something, Bob, one of the cooks, begged.', '["Cure","Ache","Heart","Ward","Rash","Drip","Fever","Organ","Heal","Pill","Cast","Ulcer","Scan","Bone","Care","Dose","Vein","Pulse","Nurse","Cell","Iron","Lung","Gene","Vital","Sepsis","Virus","Tumor","Clinic","Sterile","Bandage","Doctor","Tablet","Swab","Splint","Stitch","Asthma","Insulin","Triage","Vaccine","Rehab"]'::jsonb),
  ('bnote', 'curated', 'hidden-words', 'Bible', 'Short note', 'books of the Bible', 'I have a remark to make. The flu kept me in bed for a most boring week. Jo, eleven days later, gave me the facts. The truth is, the job was done.', '["Genesis","Exodus","Leviticus","Numbers","Deuteronomy","Joshua","Judges","Ruth","Samuel","Kings","Chronicles","Ezra","Nehemiah","Esther","Job","Psalms","Proverbs","Ecclesiastes","Isaiah","Jeremiah","Lamentations","Ezekiel","Daniel","Hosea","Joel","Amos","Obadiah","Jonah","Micah","Nahum","Habakkuk","Zephaniah","Haggai","Zechariah","Malachi","Matthew","Mark","Luke","John","Acts","Romans","Corinthians","Galatians","Ephesians","Philippians","Colossians","Thessalonians","Timothy","Titus","Philemon","Hebrews","James","Peter","Jude","Revelation"]'::jsonb),
  ('broad', 'curated', 'hidden-words', 'Bible', 'Road trip', 'books of the Bible', 'Our trip began at dawn in those amber hills. Jonah, um, drove the van. He brews coffee like a hero, man, said Mica, happily sipping it. Dani, eleven, kept a pet ermine in a box. The raja mess hall was shut, so everyone sat joking, snacks in hand. Les, there is room for one more, Mom called.', '["Genesis","Exodus","Leviticus","Numbers","Deuteronomy","Joshua","Judges","Ruth","Samuel","Kings","Chronicles","Ezra","Nehemiah","Esther","Job","Psalms","Proverbs","Ecclesiastes","Isaiah","Jeremiah","Lamentations","Ezekiel","Daniel","Hosea","Joel","Amos","Obadiah","Jonah","Micah","Nahum","Habakkuk","Zephaniah","Haggai","Zechariah","Malachi","Matthew","Mark","Luke","John","Acts","Romans","Corinthians","Galatians","Ephesians","Philippians","Colossians","Thessalonians","Timothy","Titus","Philemon","Hebrews","James","Peter","Jude","Revelation"]'::jsonb),
  ('bpeople', 'curated', 'hidden-words', 'Bible', 'People of the Bible', 'Bible names', 'Hanna omitted nothing from the list. Read a map before the trip, Tessa ultimately said. The whole ahead was sea. Tunes, autumn leaves and a belt were packed. No, a hat too. Lisa, across the room, laughed at the rod in the corner. Ada video called his lass from the docks. Nina, a Ronaldo fan, joined. Mo, sesame bread please. Pa, ultimately, was right: these things take time. Jess, especially, loved the summary of truth at the end. Mica, Lebron and Sam, son of the host, cleared up.', '["Adam","Eve","Noah","Abel","Cain","Seth","Isaac","Esau","Leah","Moses","Aaron","Ruth","Naomi","Saul","David","Jesse","Caleb","Samson","Herod","Paul","Silas","Mary","Eli","Abram","Sarah","Jacob","Rachel","Joseph","Miriam","Boaz","Elijah","Elisha","Martha","Lazarus","Andrew","Thomas","Philip","Judas","Pilate","Stephen"]'::jsonb),
  ('world', 'curated', 'hidden-words', 'Names', 'Names around the world', 'names', 'Our tour group took the van at dawn. Tom, a rat ran under a seat, Jim, I am sure of it. We sped round the castle, nap forgotten. Lulu can sing, so she did, all the way to the pool gate. Afra, just back from Oslo, was venting about fine sand in her shoes. Eureka, I found a mirror, she said, better than a comb. The table, old and rich enough for a king, stood in the hall.', '["Ivan","Omar","Lena","Raj","Mia","Leo","Kai","Pedro","Luca","Eva","Olga","Sven","Ines","Amir","Chen","Hana","Yuki","Nia","Tariq","Kofi","Arjun","Ella"]'::jsonb),
  ('legends', 'curated', 'hidden-words', 'Football', 'Football legends', 'football legends', 'Cape leaves covered the pitch. Mama, need a pen? asked Mika, nuts in hand. We ahead, the tower clock said three. I think antelopes ran past the mill, a strange sight. If I go now, okay, a yak might follow.', '["Pele","Mane","Kanu","Weah","Eto","Kante","Milla","Figo","Yaya","Salah","Okocha","Drogba","Essien","Mikel","Osimhen","Toure","Zico"]'::jsonb),
  ('body', 'curated', 'hidden-words', 'Health', 'Art class', 'body parts', 'The art class met at noon. No, seriously, the teacher said, draw a cobra in chalk. Mel, bow your head and look much in the style of the elf. Gus, pine trees go at the back. Oli, very carefully, add a taco longer than the plan, kleenex ready for spills. That humble picture won.', '["Arm","Leg","Hip","Rib","Lung","Liver","Heart","Brain","Skin","Bone","Spine","Knee","Shin","Heel","Toe","Lip","Ear","Eye","Nose","Chin","Jaw","Neck","Wrist","Ankle","Elbow","Thumb","Colon","Kidney","Gut","Skull","Palm"]'::jsonb),
  ('elements', 'curated', 'hidden-words', 'Science', 'Car trouble', 'elements', 'Our car, gone by noon, left us waiting with Bob, or one of his friends. Brad, on the phone, said Jaco, Baltimore is closer. Nick, Ellen and I went to Rio, dined, and slept. At the diner, Rocco, pepper in hand, asked Basil, very politely, to fix the car bonnet. Meg, old and wise, laughed.', '["Iron","Gold","Neon","Zinc","Tin","Lead","Argon","Xenon","Radon","Boron","Carbon","Copper","Silver","Sodium","Helium","Cobalt","Nickel","Iodine","Oxygen","Lithium","Calcium","Radium","Barium","Mercury","Arsenic","Nitrogen","Sulfur"]'::jsonb),
  ('space', 'curated', 'hidden-words', 'Science', 'Night drive', 'space words', 'Kim, Arsenal fan since seven, us included, drove up Luton way. Come to the casino van near the fair, Lulu narrowly insisted. It was a petit and quiet place, also largely empty.', '["Sun","Moon","Star","Mars","Venus","Earth","Pluto","Comet","Orbit","Nova","Saturn","Uranus","Titan","Apollo","Rocket","Lunar","Solar","Galaxy","Nebula","Meteor","Crater","Europa"]'::jsonb),
  ('ml', 'curated', 'hidden-words', 'AI', 'Match day', 'machine learning words', 'Ten, sorry, eleven players arrived at the deep ochre field. Bat, chips and a flask sat by tea stalls. Monica, chess champion, said no, deal later. Pix, Ellie from the lab, Ellie''s twin, and the rest went in, put their bags down, then sent them bed early.', '["Data","Model","Token","Agent","Bias","Chat","Loop","Train","Logic","Robot","Code","Graph","Neural","Prompt","Vector","Tensor","Layer","Weight","Output","Input","Python","Cloud","Pixel","Node","Byte","Query","Label","Embed","Epoch","Batch","Kernel","Cache","Server"]'::jsonb),
  ('cities', 'curated', 'hidden-words', 'History', 'Party time', 'ancient cities', 'The best party red balloons I own came from Mika, no joke. Ben, in a cargo south of town, brought his pet rabbit. Joy, obviously happy, said it was most, I am sure, of her life''s fun. Jerome tried to destroy the cake.', '["Rome","Troy","Athens","Sparta","Thebes","Memphis","Carthage","Babylon","Petra","Tyre","Sidon","Jericho","Delphi","Corinth","Luxor","Giza","Uruk","Susa","Argos","Pompeii","Ostia","Benin","Ife","Oyo","Kano","Timbuktu","Axum","Meroe"]'::jsonb),
  ('animals', 'curated', 'hidden-words', 'General', 'Ship shape', 'animals', 'Pati, Gerry and I sailed on the ship, pots rattling in the hot terrace kitchen. Rica, mellow as ever, told a tale, murky and long. From Japan, Dad sent a card. Jacko, Alan said Bill, a map is on the way.', '["Cat","Dog","Rat","Bat","Cow","Pig","Hen","Owl","Ape","Eel","Elk","Emu","Yak","Ant","Bee","Fox","Lion","Bear","Wolf","Deer","Goat","Hare","Mole","Seal","Crab","Frog","Toad","Duck","Swan","Lamb","Mule","Moth","Tiger","Zebra","Camel","Horse","Sheep","Llama","Panda","Koala","Otter","Hippo","Rhino","Lemur","Hyena","Eagle","Robin","Raven","Snake","Shark","Whale"]'::jsonb),
  ('fruits', 'curated', 'hidden-words', 'General', 'Market day', 'fruits', 'Adele, Monday came long before we planned. The man, gone by noon, left the top run early. Clara is in charge of ski, with Adam, son of the owner. Tom, a tortoise fan, wants to go so live music plays. At the cape, achieved at last, we paid the cash. Ewe cheese appears everywhere.', '["Apple","Pear","Plum","Fig","Date","Lime","Lemon","Mango","Melon","Kiwi","Grape","Peach","Cherry","Berry","Olive","Guava","Papaya","Banana","Orange","Lychee","Quince","Apricot","Coconut","Tomato","Avocado","Cashew","Raisin","Prune","Damson","Sultana"]'::jsonb),
  ('afrobeats', 'curated', 'hidden-words', 'Naija', 'Party at ours', 'Afrobeats stars', 'A wiz kid from our street won the quiz, so David ordered more mangoes and cola, mid evening, for everyone. We had to burn a candle when the light went, I was told, but nobody minded. This I might never forget: Auntie was a keen dancer, so we let ''em sing while she danced. Joe, boy, you should have seen her play radio hits from a hall of elaborate speakers. Grandpa wrote knowing notes about it all.', '["Wizkid","Davido","Rema","Olamide","Burna","Tiwa","Simi","Asake","Tems","Joeboy","Ayra","Omah","Fela","Tekno"]'::jsonb),
  ('nollywood', 'curated', 'hidden-words', 'Naija', 'Farm visit', 'Nollywood stars', 'At the farm, the fun kept going: two rams eyeing the gate, a former cyclist fixing a trunk unless it rained, and a toy in every hand. Tim, in it for the food, drank empty every cup. We had to sit at the back the entire time, and I also laughed. Much I did not understand, but the most angry goat calmed down when the spirit and songs rose. Book a tent next year, so much effort is saved.', '["Funke","Ramsey","Mercy","Kunle","Toyin","Timini","Nkem","Osita","Ireti","Sola","Chidi","Stan","Rita","Kate","Uche"]'::jsonb),
  ('lagos', 'curated', 'hidden-words', 'Naija', 'Aunty Mary', 'Lagos places', 'Mary landed late. Ma, go down to the market until the fest across the road ends, she said. I like jam, but Grandpa, Papa and the raja had a jar of honey instead. A taxi so loud it woke the village gets my vote for worst ride. To play a band song, the dojo taught us to mash mush into rhythm. A frog basked by the pen while a koala barked, if you can believe it. Come to join us.', '["Maryland","Magodo","Ketu","Festac","Ikeja","Apapa","Ajah","Isolo","Agege","Yaba","Ojota","Mushin","Ogba","Epe","Alaba","Ojo"]'::jsonb),
  ('eagles', 'curated', 'hidden-words', 'Naija', 'Band practice', 'Super Eagles players', 'Look, man, the main avenue was shut, so Mike left early. A bass eyed me from the stage beside the konga and a toy oboe. With milk, an uncle and his emu sat calmly while carbon I faced in class became a song. Mo''s essay on the shark fin, I did not read, and I did not ask. This I monitor from afar.', '["Lookman","Aina","Mikel","Bassey","Ekong","Yobo","Kanu","Musa","Boniface","Moses","Finidi","Ndidi","Simon"]'::jsonb)
